const assert=require('node:assert/strict'),fs=require('fs'),vm=require('vm'),path=require('path');
const M=require('../model.js'),UI=require('../c2.js'),{fixture}=require('./dom_fixture.cjs');
const ctx={window:{}};vm.runInNewContext(fs.readFileSync(path.join(__dirname,'../data/bundle.js'),'utf8'),ctx);const d=ctx.window.C2_DATA,m=M.build(d.schema,d.mapping);let checks=0;
function test(n,f){f();checks++;console.log('PASS',n)}
function assertAtlas(f){const A=f.window.TreeModel.atlas,model=f.c2.getModel(),tree=A.analysis(model),app=f.$('#c2-app'),svg=app.querySelector('.atlas-svg'),scene=A.layout(tree,{selected:f.c2.getState().selected,mode:svg.dataset.mode}),ids=app.querySelectorAll('.atlas-vertex').map(n=>n.dataset.atlasId);assert.deepEqual([...ids].sort(),JSON.parse(JSON.stringify(scene.nodes.map(n=>n.id).sort())));assert.equal(Number(svg.dataset.nodeCount),ids.length);assert.equal(Number(svg.dataset.totalCount),model.nodes.size);assert.equal(Number(svg.dataset.edgeCount),ids.length-1);assert.equal(scene.visibleCount+scene.foldedCount,model.nodes.size);assert(ids.includes(f.c2.getState().selected));return scene;}
test('72 nodes: 59 originals, 13 instances, 47 answers, six unresolved',()=>{assert.equal(m.schema.nodes.length,59);assert.equal(m.nodes.size,72);assert.equal(m.answers.size,47);assert.equal(m.questions.length,6);assert.equal(M.validate(m).length,0)});
test('entry shows complete root and all five sections, no preselected deep answer',()=>{const s=M.initial(m);assert.equal(s.focus,M.ROOT);assert.equal(s.selected,M.ROOT);assert.equal(M.branch(m,s).items.length,5)});
test('every focus node and page stays bounded and nonoverlapping without horizontal overflow',()=>{for(const width of [220,296,366,560,800,1200])for(const id of m.nodes.keys()){let s=M.locate(m,M.initial(m),id);for(let page=0;page<=M.branch(m,s).maxPage;page++){s=M.reduce(m,s,{type:'page',page});const g=M.layout(m,s,width);assert.equal(g.width,Math.max(220,width));assert.equal(typeof g.vertical,'boolean');for(const n of g.nodes){assert(n.x>=0&&n.y>=0);assert(n.x+n.w<=g.width);assert(n.y+n.h<=g.height)}for(let i=0;i<g.nodes.length;i++)for(let j=i+1;j<g.nodes.length;j++){const a=g.nodes[i],b=g.nodes[j];assert(a.x+a.w<=b.x||b.x+b.w<=a.x||a.y+a.h<=b.y||b.y+b.h<=a.y)}}}});
test('complete 72-node atlas persists at every selection with all five branches and exact selected path',()=>{const T=require('../../model.js').atlas,t=T.analysis(m);for(const id of m.nodes.keys()){const s=M.locate(m,M.initial(m),id),h=UI.overviewHtml(m,s);const scene=T.layout(t,{selected:id,mode:'semantic'});assert.equal((h.match(/class="atlas-vertex /g)||[]).length,scene.visibleCount);assert.equal(scene.visibleCount+scene.foldedCount,72);assert.equal((T.svg(t,id,'contract',{mode:'full'}).match(/class="atlas-vertex /g)||[]).length,72);for(const sec of M.SECTIONS)assert(h.includes('data-atlas-id="'+sec+'"'));assert.equal((h.match(/aria-current="true"/g)||[]).length,1);assert.equal((h.match(/class="active"/g)||[]).length,T.route(t,id).length-1)}});
test('every layer item reachable across pages and complete directory search',()=>{for(const id of m.nodes.keys()){let s=M.locate(m,M.initial(m),id);s.focus=id;const seen=[];for(let page=0;page<=M.branch(m,s).maxPage;page++){s=M.reduce(m,s,{type:'page',page});seen.push(...M.branch(m,s).items.map(n=>n.id))}assert.deepEqual(seen,M.children(m,id).map(n=>n.id))}assert.equal(M.search(m).length,72)});
function start(){const f=fixture();assert.equal(f.errors.length,0);f.c2.open('harnessvln',f.app.getContext());return f;}
test('DOM: five main branches visible from initial root',()=>{const f=start();assert.equal(f.$('#c2-app').querySelectorAll('.atlas-root').length,5);assert.equal(f.c2.getState().focus,M.ROOT);assert(f.$('.c2-canvas'));assertAtlas(f);assert.equal(f.$('#c2-tree-workspace').getAttribute('data-root-view'),'true');assert.equal(f.document.activeElement.id,'c2-node-paper-analysis-tree');assert.equal(f.$('#c2-overlay'),null)});
test('DOM: global→Method→module1→why→evidence; global remains and close returns position',()=>{const f=start();f.click('.atlas-vertex[data-atlas-view="analysis"][data-atlas-id="method"]');assert.equal(f.c2.getState().focus,'method');f.click('.c2-node[data-id="method.module1"]');f.click('.c2-node[data-id="method.module1.why"]');assert.equal(f.$('#c2-app').querySelectorAll('.atlas-root').length,5);assert(f.$('.c2-mini-current').textContent.includes('为什么能work'));assert(f.$('#c2-overlay'));assert.equal(f.c2.getState().drawer,'evidence');assert(f.$('#c2-drawer-body').textContent.includes('读者解释'));f.click('[data-c2="close"]');assert.equal(f.c2.getState().selected,'method.module1.why');f.click('[data-c2="overview"]');assert.equal(f.c2.getState().focus,M.ROOT)});
test('DOM: all unresolved including missing source remain visible',()=>{const f=start();f.click('[data-c2="unresolved"]');assert.equal(f.$$('.c2-question').length,6);assert(f.$('#c2-drawer-body').textContent.includes('源码尚未阅读'))});
test('DOM: complete directory and empty search recover',()=>{const f=start();f.click('[data-c2="directory"]');assert.equal(f.$$('.c2-directory-row').length,72);f.c2.dispatch({type:'search',query:'no-match-049390'});assert.equal(f.$$('.c2-directory-row').length,0);f.click('[data-c2="clear-search"]');assert.equal(f.$$('.c2-directory-row').length,72)});
test('DOM: history back/forward preserves branch and returns overview',()=>{const f=start();f.click('.atlas-vertex[data-atlas-view="analysis"][data-atlas-id="method"]');f.click('.c2-node[data-id="method.module1"]');f.back();assert.equal(f.c2.getState().focus,'method');f.forward();assert.equal(f.c2.getState().focus,'method.module1');f.click('[data-c2="overview"]');assert.equal(f.c2.getState().focus,M.ROOT)});
test('bounded focus changes preserve document position and history restores each recorded scroll',()=>{const f=start();f.window.scrollY=800;f.click('.atlas-vertex[data-atlas-view="analysis"][data-atlas-id="method"]');assert.equal(f.window.scrollY,800);f.window.scrollY=1000;f.click('.c2-node[data-id="method.module1"]');assert.equal(f.window.scrollY,1000);f.window.scrollY=700;f.back();assert.equal(f.window.scrollY,1000);f.forward();assert.equal(f.window.scrollY,700);f.window.innerHeight=500;f.window.scrollY=800;f.click('.atlas-vertex[data-atlas-view="analysis"][data-atlas-id="experiments"]');assert.equal(f.window.scrollY,800);f.click('[data-c2="overview"]');assert.equal(f.window.scrollY,800);assert.equal(f.document.activeElement.id,'c2-node-paper-analysis-tree');});
test('pending papers never inherit HarnessVLN evidence',()=>{const n=M.build(d.schema,d.mapping,'navgpt');assert.equal(n.nodes.size,59);assert.equal(n.answers.size,0);assert.equal(n.mapping,null)});
test('continuations retain IDs and source order but never displace substantive page slots',()=>{for(const id of m.nodes.keys()){let s=M.locate(m,M.initial(m),id);s.focus=id;const all=M.children(m,id),seen=[];for(let page=0;page<=M.branch(m,s).maxPage;page++){s=M.reduce(m,s,{type:'page',page});const b=M.branch(m,s);assert(b.items.filter(n=>!M.isContinuation(n)).length<=b.size);seen.push(...b.items.map(n=>n.id));for(const n of b.items){const located=M.locate(m,s,n.id);assert(M.branch(m,located).items.some(x=>x.id===n.id)||located.focus===n.id)}}assert.deepEqual(seen,all.map(n=>n.id))}const s=M.locate(m,M.initial(m),'method'),b=M.branch(m,s);assert.equal(b.items.filter(n=>!M.isContinuation(n)).length,4);assert(b.items.some(n=>n.id==='method.more'));assert(b.items.some(n=>n.id==='method.module3'));assert(M.layout(m,s,900).nodes.find(n=>n.id==='method.more').continuation);assert(M.layout(m,s,900).nodes.find(n=>n.id==='method.more').h>=32);});
test('lightweight original continuation is still select-able and readable from full directory',()=>{const f=start();f.click('.atlas-vertex[data-atlas-view="analysis"][data-atlas-id="method"]');assert(f.$('.c2-continuation[data-id="method.more"]'));f.click('.c2-continuation[data-id="method.more"]');assert.equal(f.c2.getState().selected,'method.more');assert.equal(f.document.activeElement.id,'c2-node-method_more');f.click('[data-c2="directory"]');assert.equal(f.$$('.c2-directory-row').length,72);f.click('.c2-directory-row[data-id="method.more"]');assert.equal(f.c2.getState().selected,'method.more');f.click('[data-c2="evidence"]');assert(f.$('#c2-drawer-body').textContent.includes('省略占位'));});
console.log(checks+' global-first contracts passed; deterministic DOM only, no browser geometry claimed');

// Continuous graphic tree contracts: the SVG scene itself retains hierarchy.
test('all 72 selections retain their section root, every expanded ancestor and actual parent edges',()=>{for(const id of m.nodes.keys()){const s=M.locate(m,M.initial(m),id),scene=M.layout(m,s,390),section=M.sectionOf(m,s.focus)||M.ROOT,ids=new Set(scene.nodes.map(n=>n.id));assert(ids.has(section));for(const ancestor of M.ancestors(m,s.focus).filter(n=>n!==M.ROOT||section===M.ROOT))assert(ids.has(ancestor),id+' lost '+ancestor);for(const edge of scene.edges)assert.equal(m.nodes.get(edge.target).parent,edge.source);assert.equal(ids.size,scene.nodes.length);}});
test('Method expansion retains its sibling modules and clicking expanded branch collapses only its children',()=>{const f=start();f.click('.atlas-vertex[data-atlas-view="analysis"][data-atlas-id="method"]');const before=f.$$('.c2-node').map(n=>n.dataset.id);f.click('.c2-node[data-id="method.module1"]');for(const id of before)assert(f.$('.c2-node[data-id="'+id+'"]'),'lost '+id);assert(f.$('.c2-node[data-id="method.module1.why"]'));assert.equal(f.$('.c2-node[data-id="method.module1"]').dataset.c2,'collapse');f.click('.c2-node[data-id="method.module1"]');assert.equal(f.c2.getState().focus,'method');assert.equal(f.$('.c2-node[data-id="method.module1.why"]'),null);assert.equal(f.$('#c2-app').querySelectorAll('.atlas-root').length,5);});
console.log('Continuous diagram: section root, ancestor path and siblings retained; actual browser QA NOT_RUN.');

// Independent-review regression: selection and expansion are distinct states.
function assertExpansionMatchesScene(f){const model=f.c2.getModel(),state=f.c2.getState(),scene=M.layout(model,state,390),expanded=new Set(M.ancestors(model,state.focus));for(const button of f.$$('.c2-node')){const id=button.dataset.id;if(!M.children(model,id).length)continue;const isExpanded=expanded.has(id);assert.equal(button.dataset.c2,isExpanded?'collapse':'enter',id+' action disagrees with focus');assert.equal(button.getAttribute('aria-expanded'),String(isExpanded),id+' ARIA disagrees with focus');assert.equal(scene.edges.some(edge=>edge.source===id),isExpanded,id+' drawing disagrees with expansion');}assert(scene.nodes.some(node=>node.id===state.selected),'selected node absent');}
test('repeated collapse and reopen uses actual expansion, preserving selected node, ancestors and siblings',()=>{const f=start();f.click('.atlas-vertex[data-atlas-view="analysis"][data-atlas-id="method"]');for(let round=0;round<4;round++){f.click('.c2-node[data-id="method.module1"]');assert.equal(f.c2.getState().focus,'method.module1');assertExpansionMatchesScene(f);assert(f.$('.c2-node[data-id="method.module1.why"]'));f.click('.c2-node[data-id="method.module1"]');assert.equal(f.c2.getState().focus,'method');assert.equal(f.c2.getState().selected,'method.module1');assert.equal(f.$('.c2-node[data-id="method.module1.why"]'),null);assertExpansionMatchesScene(f);for(const id of ['method','method.module2','method.module3'])assert(f.$('.c2-node[data-id="'+id+'"]'));}});
test('Back and history retain selection without falsely marking a collapsed child expanded',()=>{const f=start();f.click('.atlas-vertex[data-atlas-view="analysis"][data-atlas-id="method"]');f.click('.c2-node[data-id="method.module1"]');f.click('[data-c2="back"]');assert.equal(f.c2.getState().focus,'method');assert.equal(f.c2.getState().selected,'method.module1');assertExpansionMatchesScene(f);f.click('.c2-node[data-id="method.module1"]');assert.equal(f.c2.getState().focus,'method.module1');f.click('.c2-node[data-id="method.module1"]');assertExpansionMatchesScene(f);f.back();assert.equal(f.c2.getState().focus,'method.module1');assertExpansionMatchesScene(f);f.forward();assert.equal(f.c2.getState().focus,'method');assertExpansionMatchesScene(f);f.click('.c2-node[data-id="method.module1"]');assert.equal(f.c2.getState().focus,'method.module1');assertExpansionMatchesScene(f);});
test('every expandable subsection can collapse and reopen twice with scene, control and focus agreement',()=>{const f=start();for(const node of m.nodes.values()){if(node.parent===M.ROOT||node.id===M.ROOT||!M.children(m,node.id).length)continue;f.c2.dispatch({type:'enter',id:node.id});for(let round=0;round<2;round++){assertExpansionMatchesScene(f);f.click('.c2-node[data-id="'+node.id+'"]');assert.equal(f.c2.getState().focus,node.parent);assert.equal(f.c2.getState().selected,node.id);assertExpansionMatchesScene(f);f.click('.c2-node[data-id="'+node.id+'"]');assert.equal(f.c2.getState().focus,node.id);assertExpansionMatchesScene(f);}const branch=M.branch(m,f.c2.getState());for(let page=0;page<=branch.maxPage;page++){f.c2.dispatch({type:'page',page});assertExpansionMatchesScene(f);}}});
console.log('Repeated collapse/reopen, Back/Forward and all subsection states verified; no browser claim.');

test('semantic ArrowRight reveals a folded child and focuses its attached SVG control',()=>{const f=start(),model=f.c2.getModel(),child=M.children(model,'method')[0].id;assert.equal(f.$('[data-atlas-view="analysis"][data-atlas-id="'+child+'"]'),null);const parent=f.$('[data-atlas-view="analysis"][data-atlas-id="method"]');parent.focus();parent.emit('keydown',{key:'ArrowRight'});assert.equal(f.c2.getState().selected,child);assert.equal(f.document.activeElement.dataset.atlasId,child);assert(f.$('#c2-app').querySelectorAll('.atlas-vertex').includes(f.document.activeElement));assertAtlas(f);});
test('full expansion and semantic return preserve selected node, focus branch and scientific model',()=>{const f=start();f.c2.dispatch({type:'enter',id:'method.module4.how'});const state=JSON.stringify(f.c2.getState()),before=JSON.stringify([...f.c2.getModel().nodes]);f.click('[data-atlas-mode="analysis"]');assert.equal(assertAtlas(f).visibleCount,72);assert.equal(JSON.stringify(f.c2.getState()),state);f.click('[data-atlas-mode="analysis"]');assert(assertAtlas(f).foldedCount>0);assert.equal(JSON.stringify(f.c2.getState()),state);assert.equal(JSON.stringify([...f.c2.getModel().nodes]),before);});
